1	/**
2	 * Project quota, slug suggestion and the archive cascade.
3	 *
4	 * Owner C implements `@/server/services/project-service`.
5	 */
6	import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
7	
8	vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
9	vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
10	
11	import { subscribe } from "@/lib/event-bus";
12	import * as issueRepo from "@/server/repositories/issue-repository";
13	import * as projectRepo from "@/server/repositories/project-repository";
14	import * as issueService from "@/server/services/issue-service";
15	import * as projectService from "@/server/services/project-service";
16	import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
17	import type { CreateProjectInput } from "@/schemas/project";
18	import type { OrgId } from "@/types/common";
19	
20	function projectInput(
21	  orgId: OrgId,
22	  overrides: Partial<{ name: string; slug: string; key: string }> = {},
23	): CreateProjectInput {
24	  return {
25	    orgId,
26	    name: overrides.name ?? "Widget Works",
27	    slug: overrides.slug ?? "widget-works",
28	    key: overrides.key ?? "WID",
29	    description: null,
30	    visibility: "org",
31	    leadId: null,
32	    color: "#6366f1",
33	    targetDate: null,
34	  };
35	}
36	
37	let cleanup: () => void;
38	
39	beforeAll(async () => {
40	  cleanup = await useTemporaryDatabase();
41	});
42	
43	afterAll(() => {
44	  cleanup();
45	});
46	
47	describe("services/project-service", () => {
48	  it("refuses creation once the plan's project quota is reached", async () => {
49	    // `createTenant` already inserts one project, so the free plan's ceiling
50	    // of two projects is one `createProject` call away.
51	    const tenant = await createTenant("projquota", "free");
52	
53	    await projectService.createProject(
54	      tenant.actors.member,
55	      projectInput(tenant.org.id, { name: "Second Project", slug: "second", key: "SEC" }),
56	    );
57	
58	    await expect(
59	      projectService.createProject(
60	        tenant.actors.member,
61	        projectInput(tenant.org.id, { name: "Third Project", slug: "third", key: "THI" }),
62	      ),
63	    ).rejects.toThrow(/allows 2 projects/);
64	  });
65	
66	  it("suggests a suffixed slug when the requested one is taken", async () => {
67	    // `createTenant` seeds a project already slugged "platform".
68	    const tenant = await createTenant("projslug", "growth");
69	    expect(tenant.project.slug).toBe("platform");
70	
71	    await expect(
72	      projectService.suggestProjectSlug(tenant.org.id, "Platform"),
73	    ).resolves.toBe("platform-2");
74	  });
75	
76	  it("scopes slug uniqueness to the organization", async () => {
77	    const tenantA = await createTenant("slugorga", "growth");
78	    const tenantB = await createTenant("slugorgb", "growth");
79	
80	    await projectService.createProject(
81	      tenantB.actors.member,
82	      projectInput(tenantB.org.id, { name: "Rocket", slug: "rocket", key: "ROC" }),
83	    );
84	
85	    // "rocket" is taken in org B but free in org A.
86	    await expect(
