/**
 * Copies every **live** issue of `fromProjectId` into `toProjectId` for a
 * gated project clone (ADR 0012): title, description, priority, estimate,
 * due date and labels come along; status resets to `defaultStatus`, the issue
 * is unassigned, has no parent and no start/completion time, and is authored
 * by the person cloning. Renumbered from 1 in the source issues' number order.
 * Comments and attachments are never copied.
 */
export async function copyLiveIssuesForClone(
  orgId: OrgId,
  fromProjectId: ProjectId,
  toProjectId: ProjectId,
  authorId: UserId,
  defaultStatus: IssueStatus,
): Promise<readonly Issue[]> {
  const db = getDb();
  const sourceRows = db
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, fromProjectId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .orderBy(asc(issues.number))
    .all();

  const stamp = toIsoTimestamp(new Date());
  const copied: Issue[] = [];

  for (const [index, source] of sourceRows.entries()) {
    const id = newId();
    const row = db
      .insert(issues)
      .values({
        id,
        orgId,
        projectId: toProjectId,
        number: index + 1,
        title: source.title,
        description: source.description,
        status: defaultStatus,
        priority: source.priority,
        authorId,
        assigneeId: null,
        parentId: null,
        estimate: source.estimate,
        dueAt: source.dueAt,
        startedAt: null,
        completedAt: null,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .returning()
      .get();

    const labelRows = db
      .select({ labelId: issueLabels.labelId })
      .from(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.issueId, source.id),
        ),
      )
      .all();

    if (labelRows.length > 0) {
      db.insert(issueLabels)
        .values(
          labelRows.map((label) => ({
            orgId,
            issueId: id,
            labelId: label.labelId,
          })),
        )
        .run();
    }

    copied.push(toIssue(row, labelRows.map((label) => label.labelId as LabelId)));
  }

  return copied;
}

